        subid_to_fields(&subid_str);

    let sled = IdentitySled {
        wireguard_pubkey,
        mutation_index,
        is_valid: true,
        _pad: [0u8; 7],
        hashed_footprint,
        schema_uuid: parse_uuid_bytes(&env::var("SCHEMA_UUID").unwrap_or_default()),
        subid,
        subid_category,
        subid_component_type,
        subid_subject,
        subid_verb,
