    /// Subject segment, e.g. `"plugin-schema"`.
    pub subid_subject: [u8; 64],
    /// Verb segment, e.g. `"resolve"`.
    pub subid_verb: [u8; 32],
    /// Optional facet, e.g. `"read-path"` (empty = unset).
