#[async_trait]
pub trait AgentTrait: Send + Sync {
    /// Get agent type identifier
    fn agent_type(&self) -> &str;

    /// Get agent display name
    fn name(&self) -> &str;

    /// Get agent description
    fn description(&self) -> &str;

