    fn operations(&self) -> Vec<String>;

    /// Get security profile
    fn security_profile(&self) -> &SecurityProfile;

    /// Execute a task
    async fn execute(&self, task: AgentTask) -> Result<TaskResult, String>;

    /// Get agent status
