        let tools = self.tools.read().await;
        RegistryStats {
            total_registered: tools.len(),
        }
    }

    /// Check if a tool is registered
    pub async fn is_loaded(&self, name: &str) -> bool {
        let tools = self.tools.read().await;
        tools.contains_key(name)
    }

